using System.Security.Claims;using CampusPlacementManagement.Data;using CampusPlacementManagement.DTOs.RecruitmentDrives;using CampusPlacementManagement.Models;using CampusPlacementManagement.Models.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Controllers;
[ApiController,Route("api/recruitment-drives"),Authorize]
public class RecruitmentDrivesController:ControllerBase
{private readonly ApplicationDbContext _db;public RecruitmentDrivesController(ApplicationDbContext db)=>_db=db;
[Authorize(Roles="CompanyHR"),HttpPost]public async Task<IActionResult> Create(CreateRecruitmentDriveDto d){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==uid)??throw new UnauthorizedAccessException();if(!await _db.Jobs.AnyAsync(x=>x.JobId==d.JobId&&x.CreatedByHRId==hr.CompanyHRId))throw new UnauthorizedAccessException();if(!await _db.Colleges.AnyAsync(x=>x.CollegeId==d.CollegeId&&x.Status==CollegeStatus.Approved))throw new InvalidOperationException("College is not approved.");var drive=new RecruitmentDrive{JobId=d.JobId,CollegeId=d.CollegeId,DriveDate=d.DriveDate,Venue=d.Venue,Description=d.Description};await _db.RecruitmentDrives.AddAsync(drive);await _db.SaveChangesAsync();return Ok(drive);}
[HttpGet]public async Task<IActionResult> All(){var q=_db.RecruitmentDrives.Include(x=>x.Job).Include(x=>x.College).AsQueryable();return Ok(await q.AsNoTracking().ToListAsync());}
[HttpGet("{id}")]public async Task<IActionResult> Get(int id){var d=await _db.RecruitmentDrives.Include(x=>x.Job).Include(x=>x.College).FirstOrDefaultAsync(x=>x.DriveId==id);return d==null?NotFound():Ok(d);}
[Authorize(Roles="CompanyHR"),HttpPut("{id}")]public async Task<IActionResult> Update(int id,UpdateRecruitmentDriveDto dto){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==uid);var d=await _db.RecruitmentDrives.Include(x=>x.Job).FirstOrDefaultAsync(x=>x.DriveId==id);if(hr==null||d==null||d.Job.CreatedByHRId!=hr.CompanyHRId)return Forbid();d.DriveDate=dto.DriveDate;d.Venue=dto.Venue;d.Description=dto.Description;d.CollegeId=dto.CollegeId;await _db.SaveChangesAsync();return Ok(d);}
[Authorize(Roles="CompanyHR"),HttpPut("{id}/cancel")]public async Task<IActionResult> Cancel(int id){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==uid);var d=await _db.RecruitmentDrives.Include(x=>x.Job).FirstOrDefaultAsync(x=>x.DriveId==id);if(hr==null||d==null||d.Job.CreatedByHRId!=hr.CompanyHRId)return Forbid();d.Status=DriveStatus.Cancelled;await _db.SaveChangesAsync();return Ok(d);}}
